// ─── File: CrashCommitDemo.java ───
// Runnable demo: crash AFTER commit, BEFORE response → safe only with atomic idempotency.
package com.bank.crashcommit;

import java.math.BigDecimal;
import java.util.logging.*;

public class CrashCommitDemo {

    private static final Logger log = Logger.getLogger("CrashCommit");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ---- SAFE design: key + charge committed atomically ----
        PaymentStore safeStore = new PaymentStore();
        PaymentService safe = new PaymentService(safeStore);
        String key = "IDEM-RAJESH-88";

        try {
            // First attempt: charge commits, then the process "crashes" before response.
            safe.payThenCrashAfterCommit(key, "TXN-88", "SAV2001",
                    new BigDecimal("50000"));
        } catch (SimulatedCrash c) {
            log.warning("CRASH after commit, before response: " + c.getMessage());
        }
        log.info(() -> "After crash: charges for TXN-88 = " + safeStore.chargeCount());

        // Client cannot know it worked → retries with the SAME key.
        String replay = safe.pay(key, "TXN-88", "SAV2001", new BigDecimal("50000"));
        log.info(() -> "Client retry (same key) → " + replay);
        log.info(() -> "SAFE total charges = " + safeStore.chargeCount());

        // ---- BROKEN design: key written AFTER charge (dual-write) ----
        PaymentStore brokenStore = new PaymentStore();
        BrokenPaymentService broken = new BrokenPaymentService(brokenStore);
        try {
            broken.payThenCrashBetween("IDEM-X", "TXN-X", "SAV2001",
                    new BigDecimal("1000"));
        } catch (SimulatedCrash c) {
            log.warning("BROKEN crash between charge and key write");
        }
        // Retry finds NO key (it was never written) → charges AGAIN.
        broken.pay("IDEM-X", "TXN-X", "SAV2001", new BigDecimal("1000"));
        log.severe(() -> "BROKEN total charges = " + brokenStore.chargeCount()
                + " (DOUBLE CHARGE)");
    }
}

// ─── store/PaymentStore.java ───
class PaymentStore {
    private final java.util.concurrent.ConcurrentHashMap<String, String> keyResponse =
            new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.concurrent.ConcurrentHashMap<String, Boolean> uniqueTxn =
            new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.concurrent.atomic.AtomicInteger charges =
            new java.util.concurrent.atomic.AtomicInteger();

    // Atomic: record charge + key + response as ONE unit (one transaction).
    synchronized String chargeAndRecordAtomically(String key, String txnId,
                                                  String account, BigDecimal amount) {
        String existing = keyResponse.get(key);
        if (existing != null) return existing + " (replayed stored result)";
        if (uniqueTxn.putIfAbsent(txnId, Boolean.TRUE) != null) {
            String r = "ALREADY PROCESSED (unique txn)";
            keyResponse.put(key, r); return r;
        }
        charges.incrementAndGet();
        String response = "CHARGED " + account + " Rs." + amount + " txn=" + txnId;
        keyResponse.put(key, response);     // committed together with the charge
        return response;
    }
    // BROKEN: charge only (key written separately by caller).
    synchronized String chargeOnly(String txnId, String account, BigDecimal amount) {
        charges.incrementAndGet();
        return "CHARGED " + account + " Rs." + amount + " txn=" + txnId;
    }
    void writeKeyLater(String key, String response) { keyResponse.put(key, response); }
    String response(String key) { return keyResponse.get(key); }
    int chargeCount() { return charges.get(); }
}

// ─── service/PaymentService.java (SAFE) ───
class PaymentService {
    private final PaymentStore store;
    PaymentService(PaymentStore store) { this.store = store; }

    String pay(String key, String txnId, String account, BigDecimal amount) {
        return store.chargeAndRecordAtomically(key, txnId, account, amount);
    }
    // Commit happens, THEN we crash before the response is returned.
    String payThenCrashAfterCommit(String key, String txnId, String account,
                                   BigDecimal amount) {
        store.chargeAndRecordAtomically(key, txnId, account, amount); // COMMITTED
        throw new SimulatedCrash("process killed before response");    // crash
    }
}

// ─── service/BrokenPaymentService.java (UNSAFE dual-write) ───
class BrokenPaymentService {
    private final PaymentStore store;
    BrokenPaymentService(PaymentStore store) { this.store = store; }
    String pay(String key, String txnId, String account, BigDecimal amount) {
        if (store.response(key) != null)
            return store.response(key) + " (replayed)";
        String resp = store.chargeOnly(txnId, account, amount);
        store.writeKeyLater(key, resp);
        return resp;
    }
    // Charge commits, crash BEFORE the separate key write → key never recorded.
    String payThenCrashBetween(String key, String txnId, String account,
                               BigDecimal amount) {
        store.chargeOnly(txnId, account, amount);   // committed
        throw new SimulatedCrash("crash before writing key");
    }
}

class SimulatedCrash extends RuntimeException { SimulatedCrash(String m){ super(m);} }

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
